import { inject, Injectable } from '@angular/core';
import { Params } from '@angular/router';
import { LOCAL_ROUTE_CONTEXT } from './local-route-context.token';

@Injectable()
export class LocalRouterService {
  private readonly context = inject(LOCAL_ROUTE_CONTEXT, { optional: true });

  go(route?: string) {
    const ctx = this.context;
    if (ctx?.param && ctx.bind) {
      const target: Params = {};
      if (route) {
        target[ctx.param] = route;
      }
      ctx.bind.go(target);
    }
  }
}
